const {chromium}=require('playwright');const fs=require('node:fs');const assert=require('node:assert/strict');
(async()=>{
 const browser=await chromium.launch();const page=await browser.newPage({viewport:{width:1440,height:1100}});const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.route('**/app.js',route=>route.fulfill({contentType:'text/javascript',body:fs.readFileSync('app.js','utf8').replace('  // Initial state',`  window.labTest={state,get scope(){return scope},loadPreset,measurement,makeDisplayFrame,measurementResult,currentRecord,drawScope,simulateAndRender};\n  // Initial state`)}));
 await page.goto((process.env.SIMULATOR_URL || 'http://127.0.0.1:8765/'));await page.waitForTimeout(300);assert.deepEqual(errors,[]);
 const value=(name,source='CH1')=>page.evaluate(({name,source})=>labTest.measurementResult({name,source,source2:'CH2'},labTest.makeDisplayFrame(labTest.currentRecord())),{name,source});
 assert(Math.abs((await value('Frequency')).value-1000)<.1);assert(Math.abs((await value('Pk-Pk','CH2')).value-(9.4*10000/10050))<.01);assert(Math.abs((await value('RMS')).value-(Math.SQRT1_2*10000/10050))<.001);assert(Math.abs((await value('Mean')).value)<.001);
 const numeric=await page.evaluate(()=>{const t=Array.from({length:10001},(_,i)=>i*1e-6),sine=t.map(t=>Math.sin(2*Math.PI*1000*t)),square=t.map(t=>(t*1000)%1<.25?2:0);return Object.fromEntries(['Frequency','Period','RiseTime','FallTime','Cycle RMS','+Width','Duty Cycle','+Edges'].map(name=>[name,labTest.measurement(name==='Duty Cycle'||name==='+Width'?square:sine,t,name)]));});
 assert(Math.abs(numeric.Frequency-1000)<.01);assert(Math.abs(numeric.Period-.001)<1e-8);assert(Math.abs(numeric['Cycle RMS']-Math.SQRT1_2)<.002);assert(Math.abs(numeric['Duty Cycle']-25)<.2);assert(Math.abs(numeric['+Width']-.00025)<2e-6);assert(Math.abs(numeric.RiseTime-Math.asin(.8)/(Math.PI*1000))<1e-6);
 console.log('analytical measurements',numeric);
 // Per-measurement sources and eight visible slots.
 await page.selectOption('#measureSource','CH2');await page.selectOption('#measureType','Frequency');await page.click('#addMeasureBtn');assert.equal(await page.locator('#measurementRows tr').count(),4);assert.equal(await page.locator('#measurementRows tr').first().locator('td').first().textContent(),'CH1');
 for(const name of ['Mean','RMS','Period','Max']){await page.selectOption('#measureType',name);await page.click('#addMeasureBtn');}assert.equal(await page.locator('#measurementRows tr').count(),8);assert(await page.locator('#addMeasureBtn').isDisabled());await page.getByRole('button',{name:'Remove CH2 Max',exact:true}).click();assert.equal(await page.locator('#measurementRows tr').count(),7);
 // Gate a tiny region: amplitude is local, frequency cannot be inferred.
 await page.selectOption('#cursorMode','Time');await page.fill('#cursorX1','0.0001');await page.locator('#cursorX1').press('Tab');await page.fill('#cursorX2','0.00015');await page.locator('#cursorX2').press('Tab');await page.selectOption('#measureGate','Between Cursors');assert(!Number.isFinite((await value('Frequency')).value));assert((await value('Pk-Pk')).value<.4);await page.selectOption('#measureGate','Off');
 // Cursor source drives both actual canvas strokes and HTML color.
 for(const [source,rgb] of [['CH1','rgb(241, 214, 58)'],['CH2','rgb(99, 185, 255)']]){await page.selectOption('#cursorSource',source);assert.equal(await page.locator('#cursorSourceLabel').evaluate(el=>getComputedStyle(el).color),rgb);const pixels=await page.evaluate(()=>{const c=document.getElementById('scopeCanvas'),ctx=c.getContext('2d'),x=Math.round(52+730*(labTest.scope.cursor.x1/(labTest.scope.horizontal.timeDiv*10)+.5));return [...ctx.getImageData(x,120,1,1).data];});assert(pixels[3]===255);if(source==='CH1')assert(pixels[0]>pixels[2]);else assert(pixels[2]>pixels[0]);}
 // Run/Stop freezes measurements while circuit values change.
 await page.click('[data-action=runStop]');const frozen=(await value('Pk-Pk')).value;await page.fill('#amplitudeInput','2');await page.locator('#amplitudeInput').press('Tab');await page.waitForTimeout(200);assert.equal((await value('Pk-Pk')).value,frozen);await page.click('[data-action=runStop]');assert(Math.abs((await value('Pk-Pk')).value-(4*10000/10050))<.005);
 // Single must wait for a real trigger; Force captures and stops.
 await page.evaluate(()=>{labTest.scope.trigger.level=100;labTest.scope.trigger.mode='Normal';});await page.click('[data-action=single]');assert(await page.evaluate(()=>labTest.scope.singleArmed&&labTest.scope.running));await page.click('[data-action=forceTrig]');assert(await page.evaluate(()=>!labTest.scope.singleArmed&&!labTest.scope.running));await page.selectOption('#cursorSource','CH2');assert(Number.isFinite((await value('Pk-Pk')).value));
 await page.click('[data-action=runStop]');await page.click('[data-action=trigger50]');
 // Manual-aligned Measure menu and paging exposes previously inaccessible options.
 await page.click('[data-action=measure]');await page.locator('[data-soft-bottom="0"]').click();await page.locator('[data-soft-side="0"]').click();assert.equal(await page.locator('[data-soft-side="4"]').textContent(),'Next page →');await page.locator('[data-soft-side="4"]').click();assert.equal(await page.locator('[data-soft-side="0"]').textContent(),'High');
 // Statistics only count acquisitions, not redraws.
 await page.check('#measureStatistics');const before=await page.locator('#measurementRows tr').first().locator('td').nth(3).textContent();await page.selectOption('#cursorSource','CH1');assert.equal(await page.locator('#measurementRows tr').first().locator('td').nth(3).textContent(),before);
 await page.click('#menuOffBtn');await page.screenshot({path:'/tmp/simulator-scope-final.png',fullPage:true});
 await page.setViewportSize({width:390,height:844});assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));
 assert.deepEqual(errors,[]);console.log('PASS: values, 8 slots, per-source measurements, gates, cursor colors, run/stop, single, force, paged soft keys, statistics, mobile');await browser.close();
})().catch(e=>{console.error(e);process.exit(1);});
